# AIWGuard VMS build clean script.
#
# Removes ONLY build\out - every file in there is regenerated by the build:
#   aiwguard-vms.exe, server.cjs, sea-prep.blob, public\, AIWGuardVMS-Setup-*.exe
#
# Deliberately NOT touched (none of these are regenerated by the build):
#   build\vendor\mediamtx\  hand-placed vendor binary; the installer needs it
#   pwd.dat                 dev-mode password. Deleting it makes the next build
#                           recreate it with the DEFAULT password, silently
#                           changing the password baked into the exe.
#   data\                   dev runtime config / event log
#
# Usage: npm run clean
#        powershell -ExecutionPolicy Bypass -File build\clean.ps1
#
# NOTE: keep this file pure ASCII. npm runs it through Windows PowerShell 5.1,
# which mis-parses UTF-8 non-ASCII characters in script files.

$ErrorActionPreference = 'Stop'
$root   = Split-Path -Parent $PSScriptRoot
$outDir = Join-Path $root 'build\out'
$exe    = Join-Path $outDir 'aiwguard-vms.exe'

# Windows locks the image of a running exe, so build\out\aiwguard-vms.exe cannot
# be deleted while it runs (build-server.mjs stops with an error in that case).
# Only a process started FROM build\out blocks us. An installed copy
# (C:\Program Files\AIWGuardVMS\aiwguard-vms.exe) is a different file, so it is
# matched by path and left alone - a production instance keeps running.
$running = @(Get-Process -Name 'aiwguard-vms' -ErrorAction SilentlyContinue | Where-Object {
    try { $_.Path -eq $exe } catch { $false }
})
foreach ($p in $running) {
    Write-Host ("    stopping build instance: PID {0}  {1}" -f $p.Id, $p.Path) -ForegroundColor Yellow
    Stop-Process -Id $p.Id -Force
}
if ($running.Count -gt 0) {
    Start-Sleep -Milliseconds 500   # let Windows release the file handle
}

if (Test-Path $outDir) {
    Remove-Item -Recurse -Force $outDir
    Write-Host "Cleaned: $outDir" -ForegroundColor Green
} else {
    Write-Host "Nothing to clean ($outDir does not exist)" -ForegroundColor Green
}

# Fail early and loudly instead of deep inside the Inno Setup step.
$mediamtx = Join-Path $root 'build\vendor\mediamtx\mediamtx.exe'
if (-not (Test-Path $mediamtx)) {
    Write-Host "WARNING: missing $mediamtx" -ForegroundColor Yellow
    Write-Host "         'npm run build:installer' will fail. See build\vendor\mediamtx\README.md" -ForegroundColor Yellow
}
